CREATE TABLE Pipeline (
    Diameter FLOAT,
    Ending_Point VARCHAR(255),
    Pipeline_ID INTEGER PRIMARY KEY,
    Starting_Point VARCHAR(255)
);

CREATE TABLE Maintenance_Personnel (
    Maintenance_Personnel_ID INTEGER PRIMARY KEY,
    Name VARCHAR(255),
    Phone VARCHAR(255)
);

CREATE TABLE Maintenance_Activity_Record (
    Maintenance_Details VARCHAR(255),
    Maintenance_Personnel_ID INTEGER NOT NULL,
    Maintenance_Time DATETIME,
    Pipeline_ID INTEGER NOT NULL,
    PRIMARY KEY (Pipeline_ID, Maintenance_Personnel_ID, Maintenance_Time),
    FOREIGN KEY (Maintenance_Personnel_ID) REFERENCES Maintenance_Personnel(Maintenance_Personnel_ID),
    FOREIGN KEY (Pipeline_ID) REFERENCES Pipeline(Pipeline_ID)
);
